import{_ as t,o as a,c as o,ao as s}from"./chunks/framework.ucUddl5u.js";const p=JSON.parse('{"title":"The comm relay","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/comm.md","filePath":"concepts/comm.md","lastUpdated":null}'),r={name:"concepts/comm.md"};function n(c,e,i,h,d,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="The-comm-relay" tabindex="-1">The comm relay <a class="header-anchor" href="#The-comm-relay" aria-label="Permalink to &quot;The comm relay {#The-comm-relay}&quot;">​</a></h1><p>The comm relay is how sessions find and talk to each other, on one machine or across many. It has two halves with different jobs.</p><p><strong>Data at rest: the registry and the inboxes.</strong> Under <code>~/.sot-comm/</code> each host keeps a <code>registry.json</code> (every session&#39;s handle, host, workspace, and its work-state facts) and one append-only <code>inbox/&lt;handle&gt;.jsonl</code> per session. Discovery, catch-up after a sleep, and the work-state colours all read these files; nothing about them needs a live broker.</p><p><strong>Live delivery: the daemon.</strong> An instant message rides the Ship of Tools daemon — the same connection the frontend already uses. <code>comm-relay.sh send</code> hands the frame to the daemon, which broadcasts it to its connected clients; each host&#39;s listener files the frames addressed to its sessions into their inboxes and wakes the recipient if it is idle at its prompt. Because the relay reuses the backend connection, a message from a GPU server reaches a session on your laptop with no extra port or service.</p><p>The relay is <strong>live-only</strong> by design: the daemon forwards frames, it does not queue them. What makes delivery durable is the inbox on the receiving side, and what proves delivery is a reply.</p><h2 id="The-contract" tabindex="-1">The contract <a class="header-anchor" href="#The-contract" aria-label="Permalink to &quot;The contract {#The-contract}&quot;">​</a></h2><p><code>comm/PROTOCOL.md</code> is the contract every client implements — the Claude Code skill, the Codex adapter, and any future client — so all of them are mutually addressable through the same registry and inboxes. It is published here as the <a href="./../ref/comm">Comm protocol</a> reference.</p><p>For day-to-day use, see <a href="./../guide/messaging">Agents messaging each other</a>.</p>',8)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
